#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
# gen_blob.py <dir with <role>.metallib + manifest.json> <out fg_blob.h>: the metallibs as C arrays, for fg_mtl.m built with FG_EMBEDDED
import sys, os, json
d, out = sys.argv[1], sys.argv[2]; man = json.load(open(os.path.join(d, 'manifest.json')))
with open(out, 'w') as f:
    f.write('// generated by gen_blob.py: not for distribution\n#include <stddef.h>\n')
    for r in man:
        b = open(os.path.join(d, r + '.metallib'), 'rb').read()
        f.write('static const unsigned char fg_b_%s[%d] __attribute__((aligned(16))) = {' % (r, len(b)))
        for i in range(0, len(b), 64): f.write('\n' + ','.join(str(x) for x in b[i:i + 64]) + ',')
        f.write('};\n')
    f.write('static const struct { const char *role; const unsigned char *data; size_t len; unsigned tg[3]; } fg_blobs[] = {\n')
    for r, v in man.items(): f.write('  {"%s", fg_b_%s, sizeof fg_b_%s, {%d, %d, %d}},\n' % (r, r, r, *v['tg']))
    f.write('};\n')
print(len(man), 'metallibs in', out)
